package main

import (
	"fmt"
	"math/rand"
	"net"
	"time"
)

const (
	destIP   = "192.168.0.1" // Replace it with the destination IP
	destPort = 1234          // Replace it with the destination port number
)

func main() {
	rand.Seed(time.Now().UnixNano())

	spoofedIP := randomIP()
	data := randomString(10)

	conn, err := net.Dial("udp", fmt.Sprintf("%s:%d", destIP, destPort))
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	defer conn.Close()

	if err = conn.Write([]byte(data)); err != nil {
		fmt.Println("Error:", err)
		return
	}

	fmt.Printf("Sent UDP packet to %s:%d, spoofed from %s\n", destIP, destPort, spoofedIP)
}

func randomString(length int) string {
	var letters = []rune("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
	str := make([]rune, length)
	for i := range str {
		str[i] = letters[rand.Intn(len(letters))]
	}
	return string(str)
}

func randomIP() string {
	return fmt.Sprintf("%d.%d.%d.%d", rand.Intn(256), rand.Intn(256), rand.Intn(256), rand.Intn(256))
}
```

