for (int j = 0; j < NUM_TEXTURES; j++)
{
SDL_Texture* tmp = IMG_LoadTexture(renderer, texturePaths[i][j].c_str());
drum.textures.push_back(tmp);
}

drums.push_back(drum);
}
}

