using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class EnemySpawner : MonoBehaviour
{
    public GameObject enemyPrefab;
    public float spawnTime = 10f;
    public Vector2[] spawnPositions;
    public float minX = -6f;
    public float maxX = 6f;
    public float minY = -3.5f;
    public float maxY = 3.5f;

    private void Start()
    {
        // Start spawning enemies
        StartCoroutine(SpawnEnemies());
    }

    private IEnumerator SpawnEnemies()
    {
        while (true)
        {
            // Iterate through each spawn position
            for (int i = 0; i < spawnPositions.Length; i++)
            {
                // Randomly generate x and y coordinates within the specified range
                float randomX = Random.Range(minX, maxX);
                float randomY = Random.Range(minY, maxY);

                // Create a new spawn position using the random coordinates
                Vector2 spawnPosition = new Vector2(randomX, randomY);

                // Spawn enemy at the current position
                Instantiate(enemyPrefab, spawnPosition, Quaternion.identity);
            }

            // Wait for the specified spawn time
            yield return new WaitForSeconds(spawnTime);
        }
    }
}

Elasticsearch查询是指使用Elasticsearch查询语言，通过Elasticsearch搜索和过滤文档。以下是一些Elasticsearch查询的示例：

1. 匹配查询：根据指定条件进行匹配

```
{
  "query": {
    "match": {
      "user": "kimchy"
    }
  }
}
```

2. 多条件匹配查询：匹配多个条件

```
{
  "query": {
    "bool": {
      "must": [
        { "match": { "title": "Search" }},
        { "match": { "content": "Elasticsearch" }}
      ]
    }
  }
}
```

3. 范围查询：查询满足指定范围内条件的文档

```
{
  "query": {
    "range": {
      "age": {
        "gte": 18,
        "lte": 30
      }
    }
  }
}
```

4. 前缀查询：查询具有特定前缀的文档

```
{
  "query": {
    "prefix": {
      "user": "ki"
    }
  }
}
```

5. 正则表达式查询：使用正则表达式匹配文档

```
{
  "query": {
    "regexp": {
      "user": "k.*y"
    }
  }
}
```

6. 模糊查询：对于可能存在拼写错误的查询，进行文档匹配

```
{
  "query": {
    "fuzzy": {
      "user": {
        "value": "kimmchy",
        "fuzziness": "2",
        "prefix_length": 1,
        "max_expansions": 100
      }
    }
  }
}
```

