	timer.set_wait_time(update_rate)
	timer.set_one_shot(false)

	# Create a Callable by referencing the method directly
	var callable = Callable(self, "update_grid")

	# Use the Callable to connect the signal
	timer.connect("timeout", callable)

	add_child(timer)
	timer.start()

func initialize_grid():
	grid = []
	for y in range(grid_size.y):
		var row = []
		for x in range(grid_size.x):
			row.append(randi() % 2) # Randomly set initial state to 0 or 1
		grid.append(row)

func draw_grid():
	for y in range(grid_size.y):
		for x in range(grid_size.x):
			var tile_id = wall_tile_id if grid[y][x] == 1 else floor_tile_id
			tilemap.set_cell(x, y, tile_id)

func get_cell(x, y):
	if x < 0 or x >= grid_size.x or y < 0 or y >= grid_size.y:
		return 0
	return grid[y][x]

func count_neighbors(x, y):
	var count = 0
	for i in range(-1, 2):
		for j in range(-1, 2):
			if i == 0 and j == 0:
				continue
			count += get_cell(x + i, y + j)
	return count

func update_grid():
	var new_grid = []
	for y in range(grid_size.y):
		new_grid.append(grid[y].duplicate())

	for y in range(grid_size.y):
		for x in range(grid_size.x):
			var neighbors = count_neighbors(x, y)
			if grid[y][x] == 1 and (neighbors < 2 or neighbors > 3):
				new_grid[y][x] = 0 # Cell dies, becomes floor
			elif grid[y][x] == 0 and neighbors == 3:
				new_grid[y][x] = 1 # Cell becomes alive, becomes wall
	grid = new_grid
	draw_grid()
```

This script assumes you have a valid tilemap with floor and wall tiles already set up in your project, and their IDs set to `floor_tile_id` and `wall_tile_id` respectively. Adjust these IDs based on how your tileset is configured. Also, ensure that the `$TileMap` path correctly points to your TileMap node.

With these changes, your script will set tilemap cells to either a wall or a floor based on the results of the `update_grid` logic. This can be further adapted to represent other game mechanics or visualization needs you might have.

