```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>

int main() {
    // Open the text file for reading
    std::ifstream inputFile("input.txt");
    if (!inputFile.is_open()) {
        std::cout << "Failed to open the file." << std::endl;
        return 1;
    }

    // Read the text from the file
    std::stringstream buffer;
    buffer << inputFile.rdbuf();
    std::string text = buffer.str();
    inputFile.close();

    // Initialize variables
    std::vector<std::string> items;
    std::stringstream currentItem;

    // Extract items from the text
    for (char c : text) {
        if (c == '(' || c == ')' || c == '*' || c == '+' || c == '-' || c == '/') {
            // Push the current item if not empty
            if (!currentItem.str().empty()) {
                items.push_back(currentItem.str());
                currentItem.str(std::string());
            }

            // Push the operator as a separate item
            items.push_back(std::string(1, c));
        } else if (std::isalnum(c) || c == '.') {
            // Append alphanumeric characters to the current item
            currentItem << c;
        } else if (c == ' ') {
            // Push the current item if not empty
            if (!currentItem.str().empty()) {
                items.push_back(currentItem.str());
                currentItem.str(std::string());
            }
        }
    }

    // Push the last item if not empty
    if (!currentItem.str().empty()) {
        items.push_back(currentItem.str());
    }

    // Print the extracted items
    for (const auto& item : items) {
        std::cout << item << std::endl;
    }

    return 0;
}
```

